/* One character per pixel, and the character is where the
 * colour is in the palette. */
static const char alphabet[] =
    "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijk"
    "lmnopqrstuvwxyz!#$%&()*+,-./:;<=>?@[]^_`{|}~";

static void unpack(ween_color *dst, const char *const *rows,
                   const ween_color *pal, int w, int h)
{
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
            dst[y * w + x] =
                pal[(int)(strchr(alphabet, rows[y][x]) - alphabet)];
}

static ween_color history_px[1024];
static ween_color desktop_px[1024];
static ween_color documents_px[1024];
static ween_color computer_px[1024];
static ween_color network_px[1024];
static ween_color toolbar_px[2760];
static ween_color lookin_px[256];
static ween_color document16_px[256];

/* Each picture, unpacked once and kept. */
const ween_shell_art *ween_shell_picture(int which)
{
    static ween_shell_art art[8];
    static int done;
    if (!done) {
        art[0].w = 32;
        art[0].h = 32;
        art[0].px = history_px;
        unpack(history_px, history_rows, history_pal, 32, 32);
        art[1].w = 32;
        art[1].h = 32;
        art[1].px = desktop_px;
        unpack(desktop_px, desktop_rows, desktop_pal, 32, 32);
        art[2].w = 32;
        art[2].h = 32;
        art[2].px = documents_px;
        unpack(documents_px, documents_rows, documents_pal, 32, 32);
        art[3].w = 32;
        art[3].h = 32;
        art[3].px = computer_px;
        unpack(computer_px, computer_rows, computer_pal, 32, 32);
        art[4].w = 32;
        art[4].h = 32;
        art[4].px = network_px;
        unpack(network_px, network_rows, network_pal, 32, 32);
        art[5].w = 120;
        art[5].h = 23;
        art[5].px = toolbar_px;
        unpack(toolbar_px, toolbar_rows, toolbar_pal, 120, 23);
        art[6].w = 16;
        art[6].h = 16;
        art[6].px = lookin_px;
        unpack(lookin_px, lookin_rows, lookin_pal, 16, 16);
        art[7].w = 16;
        art[7].h = 16;
        art[7].px = document16_px;
        unpack(document16_px, document16_rows, document16_pal, 16, 16);
        done = 1;
    }
    if (which < 0 || which >= 8)
        return NULL;
    return &art[which];
}
